"use client";

import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import { Radio as RadioPrimitive } from "@base-ui/react/radio";

import { cn } from "@/lib/utils";
import { focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Bold retail RadioGroup: a column of choices with 0.75rem between them. */
function RadioGroup({
  className,
  ...props
}: WithClassName<RadioGroupPrimitive.Props>) {
  return (
    <RadioGroupPrimitive
      data-slot="radio-group"
      className={cn("grid gap-3", className)}
      {...props}
    />
  );
}
RadioGroup.displayName = "RadioGroup";

/**
 * Bold retail RadioGroupItem: a 1.25rem white circle with a grey edge.
 * Chosen, the edge turns black and a black dot sits at the centre, the same
 * flat black as the primary button.
 */
function RadioGroupItem({
  className,
  ...props
}: WithClassName<RadioPrimitive.Root.Props>) {
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      className={cn(
        "flex aspect-square size-5 shrink-0 items-center justify-center rounded-full border border-(--control) bg-background",
        "transition-colors duration-fast ease-out",
        "hover:border-foreground",
        focusRing,
        "data-[checked]:border-primary",
        "data-[disabled]:cursor-not-allowed data-[disabled]:border-(--line-strong) data-[disabled]:bg-secondary",
        className,
      )}
      {...props}
    >
      <RadioPrimitive.Indicator
        data-slot="radio-group-indicator"
        className="flex size-full items-center justify-center"
      >
        <span className="block size-2.5 rounded-full bg-primary in-data-[disabled]:bg-(--foreground-disabled)" />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  );
}
RadioGroupItem.displayName = "RadioGroupItem";

export { RadioGroup, RadioGroupItem };
